INSERT INTO `pp_pages_desc` (`page_id`, `lang`, `page_slug`, `page_title`, `page_short`, `page_detail`, `seo_title`, `seo_description`) VALUES
(1, 'vi', 'gioi-thieu', 'Giới thiệu', '', '<div class=\"row\">\r\n<div class=\"col-md-6\"><img alt=\"Giới thiệu công ty thiết kế web Panpic\" class=\"img-fluid\" src=\"http://panpicv3.local/media/images/gioi-thieu-cong-ty-thiet-ke-web-panpic.png\" /></div>\r\n\r\n<div class=\"col-md-6\">\r\n<h4 style=\"text-align: justify;\"><em>&quot;Mục ti&ecirc;u của PANPIC l&agrave; th&uacute;c đẩy &aacute;p dụng c&aacute;c&nbsp;kỹ thuật lập tr&igrave;nh ti&ecirc;n tiến v&agrave;o c&aacute;c dự &aacute;n phần mềm&nbsp;website doanh nghiệp&nbsp;tại Việt Nam nhằm tăng hiệu quả hoạt động cho doanh nghiệp&nbsp;th&ocirc;ng qua website đẳng cấp&nbsp;uy t&iacute;n, tốc độ&nbsp;tải trang nhanh&nbsp;v&agrave; n&acirc;ng cao h&igrave;nh ảnh thương hiệu.<br />\r\n<br />\r\nĐể ho&agrave;n th&agrave;nh sứ mệnh đ&oacute;, PANPIC c&ugrave;ng với đội ngũ c&aacute;n kỹ thuật lập tr&igrave;nh vi&ecirc;n&nbsp;gi&agrave;u kinh nghiệm, kiến thức v&agrave; tr&agrave;n đầy nhiệt huyết, lu&ocirc;n l&agrave;m việc hướng tới phương ch&acirc;m &ldquo;Great website great business&rdquo; cam kết mang tới cho kh&aacute;ch h&agrave;ng c&aacute;c dịch vụ với gi&aacute; trị gia tăng cao nhất&quot;</em></h4>\r\n\r\n<div class=\"row d-flex align-items-center pt-4\">\r\n<div class=\"colsm-12 col-md-12\">\r\n<div class=\"col-sm-12 col-md-12 pt-6\"><em><strong>CEO &ndash; Nguyễn Văn B&agrave;ng</strong></em></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<h4 class=\"pt-6\">TỔNG QUAN C&Ocirc;NG TY THIẾT KẾ WEB PANPIC</h4>\r\n\r\n<div class=\"col-12 col-sm-12 col-md-12 pt-6\">\r\n<div class=\"p-3 mb-2 bg-primary text-white\">\r\n<div class=\"row justify-content-center\">\r\n<div class=\"col-12 col-sm-12 col-md-11\">\r\n<div class=\"row\">\r\n<div class=\"col-12 col-sm-12 col-md-12\">\r\n<div class=\"table-responsive\">\r\n<table class=\"table text-white\">\r\n	<tbody>\r\n		<tr>\r\n			<td>T&ecirc;n c&ocirc;ng ty:</td>\r\n			<td class=\"text-white\">C&ocirc;ng Ty TNHH C&ocirc;ng Nghệ Panpic</td>\r\n		</tr>\r\n		<tr>\r\n			<td>T&ecirc;n tiếng Anh:</td>\r\n			<td class=\"text-white\">Panpic Co.,Ltd</td>\r\n		</tr>\r\n		<tr>\r\n			<td>T&ecirc;n viết tắt:</td>\r\n			<td class=\"text-white\">PANPIC</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Trụ sở ch&iacute;nh:</td>\r\n			<td class=\"text-white\">672/1/29 L&ecirc; Văn Khương, P. Thới An, Q.12, TP HCM</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Văn ph&ograve;ng giao dịch:</td>\r\n			<td class=\"text-white\">23/1 Mai L&atilde;o Bạng, Phường 13, Quận T&acirc;n B&igrave;nh, TP.HCM</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Đại diện ph&aacute;p luật:</td>\r\n			<td class=\"text-white\">&Ocirc;ng NGUYỄN VĂN B&Agrave;NG</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Năm th&agrave;nh lập:</td>\r\n			<td class=\"text-white\">2013</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Điện thoại:</td>\r\n			<td class=\"text-white\">02866 85 8 394</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Email:</td>\r\n			<td class=\"text-white\">contact@panpic.vn</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Website:</td>\r\n			<td class=\"text-white\">panpic.vn - panpic.com.vn</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Lĩnh vực hoạt động ch&iacute;nh:</td>\r\n			<td class=\"text-white\">\r\n			<ul class=\"pt-2 mb-1\">\r\n				<li>THIẾT KẾ WEBSITE</li>\r\n				<li>LẬP TR&Igrave;NH PHẦN MỀM</li>\r\n				<li>CHĂM S&Oacute;C BẢO TR&Igrave; QUẢN L&Yacute; WEBSITE</li>\r\n			</ul>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<h4 class=\"pt-6\">GIỚI THIỆU</h4>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-12 text-justify\"><strong class=\"text-primary\">C&Ocirc;NG TY&nbsp;TNHH C&Ocirc;NG NGHỆ PANPIC</strong>&nbsp;được th&agrave;nh lập v&agrave;o năm 2013, tự h&agrave;o l&agrave; agency lập tr&igrave;nh v&agrave; thiết kế web h&agrave;ng đầu tại Việt Nam,&nbsp;ti&ecirc;n phong đầu ti&ecirc;n trong việc ứng dụng giải ph&aacute;p CNTT lập tr&igrave;nh&nbsp;phần mềm v&agrave; thiết kế&nbsp;website đẹp, thẩm mỹ cao, c&ugrave;ng với quy tr&igrave;nh sản xuất phần mềm chặt chẽ nhằm tạo ra những <strong>phần mềm thuận tiện</strong> v&agrave; <strong>dễ d&agrave;ng cho người sử dụng</strong> nhất.<br />\r\n<br />\r\nCh&uacute;ng t&ocirc;i lu&ocirc;n cập nhật những c&ocirc;ng nghệ&nbsp;mới nhất trong ng&agrave;nh về ti&ecirc;u chuẩn kỹ thuật, thẩm mỹ, giải ph&aacute;p lập tr&igrave;nh&nbsp;đồng thời lu&ocirc;n cải tiến chất lượng dịch vụ nhằm giữ vững uy t&iacute;n của agency h&agrave;ng đầu&nbsp;tin cậy được kh&aacute;ch h&agrave;ng ghi nhận trong suốt thời gian qua. Với tr&ecirc;n 200 dự &aacute;n phần mềm v&agrave; thiết kế website đ&atilde; ho&agrave;n th&agrave;nh trong nước v&agrave; nước ngo&agrave;i, c&ugrave;ng đội ngũ nh&acirc;n sự kinh nghiệm, được đ&agrave;o tạo tốt, PANPIC đ&atilde; khẳng định được vị thế của m&igrave;nh l&agrave; agency lập tr&igrave;nh phần mềm v&agrave; thiết kế website h&agrave;ng đầu tại Việt Nam.<br />\r\n<br />\r\nBằng kh&aacute;t vọng ti&ecirc;n phong c&ugrave;ng chiến lược ph&aacute;t triển bền vững. PANPIC phấn đấu trở th&agrave;nh c&ocirc;ng ty thiết kế phần mềm &amp; tư vấn giải ph&aacute;p CNTT c&oacute; uy tin v&agrave; vị thế tr&ecirc;n bản đồ Việt Nam v&agrave; bản đồ thế giới, bằng c&aacute;ch cung cấp c&aacute;c sản phẩm dịch vụ CNTT chất lượng &amp; chuy&ecirc;n nghiệp, từng bước n&acirc;ng tầm vị thế dịch vụ CNTT Việt Nam tr&ecirc;n trường quốc tế.<br />\r\n<br />\r\nCh&uacute;ng t&ocirc;i ch&agrave;o đ&oacute;n Qu&yacute; Đối t&aacute;c - Kh&aacute;ch h&agrave;ng tới tham quan t&igrave;m hiểu&nbsp;c&aacute;c dự &aacute;n phần mềm v&agrave; website&nbsp;ch&uacute;ng t&ocirc;i đ&atilde; v&agrave; đang triển khai để hai b&ecirc;n c&oacute; cơ hội chia sẻ t&igrave;m ra&nbsp;giải ph&aacute;p tại PANPIC c&ugrave;ng&nbsp;những gi&aacute; trị, những kinh nghiệm được chắt lọc từ h&agrave;ng trăm&nbsp;dự &aacute;n lập tr&igrave;nh phần mềm v&agrave; thiết kế website.<br />\r\n<em><strong>PANPIC</strong></em></div>\r\n</div>\r\n', 'Giới thiệu tổng quan công ty thiết kế web hàng đầu Việt Nam', 'Giới thiệu tổng quan công ty thiết kế web hàng đầu Việt Nam'),
(2, 'vi', 'lien-he', 'Liên hệ', '', '<h6 class=\"text-primary\">Li&ecirc;n hệ b&aacute;o gi&aacute;</h6>\r\n\r\n<div>Kh&aacute;ch h&agrave;ng sử dụng th&ocirc;ng tin li&ecirc;n hệ b&ecirc;n dưới hoặc mẫu form b&ecirc;n cạnh.\r\n<ul class=\"navbar-nav nav-contact\">\r\n	<li>Th&ocirc;ng tin y&ecirc;u cầu thiết kế website chi tiết, tham khảo b&agrave;i:</li>\r\n	<li>&gt;&gt; <a href=\"http://panpicv3.local/faq/cach-soan-chuc-nang-yeu-cau-thiet-ke-web-nhu-nao\" target=\"_blank\">C&aacute;ch soạn chức năng y&ecirc;u cầu thiết kế web như thế n&agrave;o?</a></li>\r\n</ul>\r\n</div>\r\n\r\n<h6 class=\"text-primary mt-3\">Văn ph&ograve;ng</h6>\r\n\r\n<ul class=\"navbar-nav nav-contact\">\r\n	<li class=\"nav-item\"><i class=\"bi bi-geo-alt-fill\"></i> <span>Địa chỉ : 23/1 Mai L&atilde;o Bạng, P.13, Q. T&acirc;n B&igrave;nh, TP. HCM</span></li>\r\n	<li class=\"nav-item\"><i class=\"bi bi-telephone-fill\"></i> <span>Điện thoại: 0986 97 38 97 (Zalo, Whatsapp, Telegram) - 02866 85 83 94</span></li>\r\n	<li class=\"nav-item\"><i class=\"bi bi-envelope-fill\"></i> <span>Email: contact@panpic.vn</span></li>\r\n	<li class=\"nav-item\"><i class=\"bi bi-globe2\"></i> <span>Website: panpic.vn</span></li>\r\n</ul>\r\n', 'Liên hệ công ty thiết kế web doanh nghiệp đẹp Panpic', 'Liên hệ công ty thiết kế web doanh nghiệp đẹp Panpic'),
(3, 'vi', 'lich-su-pha-trien', 'Lịch sử phát triển', '', '<p><img alt=\"\" src=\"http://panpic-technology.com/pmec/media/2021/files/LICH%20SU%20HINH%20THANH.png\" style=\"width: 1024px; height: 577px;\" /></p>\r\n', 'Lịch sử phát triển', 'Lịch sử phát triển'),
(4, 'vi', 'khach-hang', 'Khách hàng', '', '', 'Đối tác khách hàng của công ty xây dựng', 'Đối tác khách hàng của công ty xây dựng PMEC'),
(7, 'vi', 'co-cau-to-chuc', 'Cơ cấu tổ chức', '', '<div class=\"text-center\"><img alt=\"PANPIC cơ cấu tổ chức công ty lập trình web\" src=\"http://panpicv3.local/media/images/Panpic-co-cau-to-chuc-cong-ty-lap-trinh-web.jpg\" /></div>\r\n', 'Cơ cấu tổ chức công ty lập trình web PANPIC', 'Cơ cấu tổ chức công ty lập trình web PANPIC'),
(8, 'vi', 'gia-tri-cot-loi', 'Giá trị cốt lõi', '', '<div class=\"text-center\">\r\n<div style=\"text-align:center\">\r\n<figure class=\"image\" style=\"display:inline-block\"><img alt=\"PANPIC giá trị cốt lõi Core value\" src=\"http://panpicv3.local/media/images/panpic-gia-tri-cot-loi-core-value.png\" />\r\n<figcaption>PANPIC gi&aacute; trị cốt l&otilde;i - Core value</figcaption>\r\n</figure>\r\n</div>\r\n</div>\r\n\r\n<h4><strong>VĂN H&Oacute;A C&Ocirc;NG TY</strong></h4>\r\n\r\n<p>Văn h&oacute;a c&ocirc;ng ty c&oacute; bản sắc l&agrave; yếu tố ti&ecirc;n quyết mang lại sự th&agrave;nh c&ocirc;ng l&acirc;u d&agrave;i cho một c&ocirc;ng ty agency lập tr&igrave;nh v&agrave; thiết kế web. Ở <strong>PANPIC</strong>, ch&uacute;ng t&ocirc;i đ&atilde; x&acirc;y dựng một văn h&oacute;a đo&agrave;n kết tập thể c&ugrave;ng chia sẻ tr&ecirc;n nền tảng t&ocirc;n trọng kỷ cương c&ocirc;ng ty, thượng t&ocirc;n ph&aacute;p luật v&agrave; đạo đức nghề nghiệp. Những nh&acirc;n sự của <strong>PANPIC </strong>từ cấp l&atilde;nh đạo đến nh&acirc;n vi&ecirc;n lu&ocirc;n hướng đến sự chuẩn mực trong c&ocirc;ng việc chuy&ecirc;n m&ocirc;n v&agrave; gi&aacute; trị nh&acirc;n văn trong x&atilde; hội để giữ vững niềm tin từ đối t&aacute;c, kh&aacute;ch h&agrave;ng v&agrave; uy t&iacute;n của C&ocirc;ng ty.<br />\r\n<br />\r\nTại <strong>PANPIC </strong>ch&uacute;ng t&ocirc;i kh&ocirc;ng đơn thuần quan t&acirc;m đến mục ti&ecirc;u mở rộng doanh số. Điều ch&uacute;ng t&ocirc;i thực sự ch&uacute; trọng l&agrave; l&agrave;m sao sử dụng c&aacute;c <strong>c&ocirc;ng nghệ mới v&agrave; độc đ&aacute;o</strong> để g&oacute;p phần <strong>xầy dựng văn h&oacute;a v&agrave; cuộc sống tốt đẹp hơn</strong>.</p>\r\n', 'PANPIC Giá trị cốt lõi', 'PANPIC Giá trị cốt lõi'),
(9, 'vi', 'can-bo-chu-chot', 'Cán bộ chủ chốt', '', '<div class=\"row\">\r\n<div class=\"col-md-6\"><img alt=\"PMEC Phan Đăng Thiêm\" class=\"img-fluid\" src=\"http://panpic-technology.com/pmec/media/2021/images/gioithieu/pmec-phan-dinh-thien.jpg\" style=\"width: 596px; height: 340px;\" /></div>\r\n\r\n<div class=\"col-md-6\">\r\n<h4 style=\"text-align: justify;\"><em>&quot;Gia nhập C&ocirc;ng ty Ph&uacute; Mỹ từ những ng&agrave;y đầu mới th&agrave;nh lập, &Ocirc;ng Phan Đăng Thi&ecirc;m phụ tr&aacute;ch việc quản l&yacute; thi c&ocirc;ng c&aacute;c dự &aacute;n, đến nay cũng được hơn mười lăm năm kinh nghiệm trong lĩnh vực thi c&ocirc;ng c&aacute;p dự ứng lực.<br />\r\n<br />\r\nTrải qua hơn ba trăm dự &aacute;n lớn nhỏ tr&ecirc;n khắp cả nước v&agrave; nước ngo&agrave;i, &Ocirc;ng v&agrave; c&aacute;c đ&ocirc;ng sự của m&igrave;nh lu&ocirc;n &aacute;p dụng phương ch&acirc;m: &quot;Uy t&iacute;n - Chất lượng - An to&agrave;n - Hiệu quả&quot; cho từng sản phẩm, dịch vụ của c&ocirc;ng ty&quot;</em></h4>\r\n\r\n<div class=\"row d-flex align-items-center pt-5\">\r\n<div class=\"colsm-12 col-md-12\">\r\n<div class=\"col-sm-12 col-md-12 pt-5\"><em><strong>Gi&aacute;m đốc khối thi c&ocirc;ng &ndash; Phan Đăng Thi&ecirc;m</strong></em></div>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div id=\"image-map\"><em><em><strong><strong><img alt=\"\" src=\"http://panpic-technology.com/pmec/media/2021/files/Hinhnhansuchuchot-VN.png\" style=\"width: 825px; height: 466px;\" /></strong></strong></em></em></div>\r\n\r\n<p><em><em><strong><strong><map name=\"map\"><area coords=\"231, 226, 116, 115, 233, 1, 350, 114\" id=\"k1\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Nguyễn Văn Long\" /> <area coords=\"470, 1, 357, 113, 474, 228, 589, 113\" id=\"k2\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Vũ Văn Sơn\" /> <area coords=\"595, 113, 711, 1, 823, 113, 714, 229\" id=\"k3\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Lê Văn Cường\" /> <area coords=\"113, 118, -1, 233, 115, 348, 232, 233\" id=\"k4\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Đỗ Bá Tùng\" /> <area coords=\"354,120,241,230,354,345,468,234\" id=\"k5\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Phan Đăng Thiêm\" /> <area coords=\"592, 116, 477, 231, 591, 347, 707, 235\" id=\"k6\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Trần Thu Nga\" /> <area coords=\"233, 239, 118, 353, 235, 465, 351, 352\" id=\"k7\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Lê Quang Định\" /> <area coords=\"471, 239, 356, 351, 473, 464, 589, 353\" id=\"k8\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Trần Quốc Anh\" /> <area coords=\"713, 236, 594, 350, 711, 465, 822, 357, 822, 357\" id=\"k9\" shape=\"poly\" style=\"cursor: pointer;\" title=\"Nguyễn Nhật Minh\" /></map><!--row 1--></strong></strong></em></em></p>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"180\" data-ypos=\"60\" id=\"k1_content\">\r\n<h4><em><em><strong><strong>Nguyễn Văn Long</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Gi&aacute;m đốc chi nh&aacute;nh h&agrave; nội</strong></strong></em></em></p>\r\n</div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"412\" data-ypos=\"60\" id=\"k2_content\">\r\n<h4><em><em><strong><strong>Vũ Văn Sơn</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Gi&aacute;m đốc kinh doanh</strong></strong></em></em></p>\r\n</div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"644\" data-ypos=\"60\" id=\"k3_content\">\r\n<h4><em><em><strong><strong>L&ecirc; Văn Cường</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Trưởng ph&ograve;ng nh&acirc;n sự</strong></strong></em></em></p>\r\n</div>\r\n\r\n<p><em><em><strong><strong><!--row 2--> </strong></strong></em></em></p>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"65\" data-ypos=\"175\" id=\"k4_content\">\r\n<h4><em><em><strong><strong>Đỗ B&aacute; T&ugrave;ng</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Ph&oacute; ph&ograve;ng thiết kế</strong></strong></em></em></p>\r\n</div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"297\" data-ypos=\"175\" id=\"k5_content\">\r\n<h4><em><em><strong><strong>Phan Đăng Thi&ecirc;m</strong></strong></em></em></h4>\r\n<em><em><strong><strong>Gi&aacute;m đốc khối thi c&ocirc;ng</strong></strong></em></em></div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"527\" data-ypos=\"175\" id=\"k6_content\">\r\n<h4><em><em><strong><strong>Trần Thu Nga</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Trưởng bộ phận c&ocirc;ng nợ</strong></strong></em></em></p>\r\n</div>\r\n\r\n<p><em><em><strong><strong><!--row 3--> </strong></strong></em></em></p>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"180\" data-ypos=\"290\" id=\"k7_content\">\r\n<h4><em><em><strong><strong>L&ecirc; Quang Định</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Gi&aacute;m đốc dự &aacute;n</strong></strong></em></em></p>\r\n</div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"412\" data-ypos=\"290\" id=\"k8_content\">\r\n<h4><em><em><strong><strong>Trần Quốc &Aacute;nh</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Gi&aacute;m đốc thiết kế</strong></strong></em></em></p>\r\n</div>\r\n\r\n<div class=\"pin pin-down\" data-xpos=\"644\" data-ypos=\"290\" id=\"k9_content\">\r\n<h4><em><em><strong><strong>Nguyễn Minh Nhật</strong></strong></em></em></h4>\r\n\r\n<p><em><em><strong><strong>Trưởng ph&ograve;ng kinh doanh</strong></strong></em></em></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n', 'PMEC Cán bộ chủ chốt', 'PMEC Cán bộ chủ chốt'),
(10, 'vi', 'tuyen-dung', 'Tuyển dụng', '', '<p><strong>Ứng vi&ecirc;n c&oacute; thể nộp hồ sơ v&agrave; đơn xin việc theo c&aacute;c h&igrave;nh thức sau</strong>:<br />\r\n<br />\r\n<strong>1</strong>. Gửi hồ sơ ứng vi&ecirc;n đến email C&ocirc;ng Ty TNHH C&ocirc;ng Nghệ Panpic.<br />\r\nEmail: <a href=\"mailto:contact@panpic.vn\">contact@panpic.vn</a><br />\r\n<br />\r\n<strong>2</strong>. Gửi hồ sơ ứng vi&ecirc;n qua form ứng tuyển trực tuyến như b&ecirc;n cạnh.<br />\r\n<br />\r\n<strong>3</strong>. Nộp hồ sơ trực tiếp tại địa chỉ C&ocirc;ng Ty TNHH C&ocirc;ng Nghệ Panpic.<br />\r\nĐịa chỉ: 23/1 Mai L&atilde;o Bạng, P. 13, Q. T&acirc;n B&igrave;nh, TP. HCM<br />\r\nĐiện thoại:&nbsp;02866 85 83 94</p>\r\n', 'Tuyển dụng', 'Tuyển dụng'),
(11, 'vi', 'cam-ket-chat-luong', 'Cam kết chất lượng', '', '<h2 id=\"h-cam-k-t-ch-t-l-ng-d-ch-v-s-n-ph-m-ph-n-m-m-website\">Cam Kết Chất Lượng Dịch Vụ Sản Phẩm Phần Mềm Website</h2>\r\n\r\n<p>C&aacute;c sản phẩm viễn th&ocirc;ng, tin học (<strong>website</strong>) cũng l&agrave; một mặt h&agrave;ng như c&aacute;c mặt h&agrave;ng kh&aacute;c, do vậy cũng c&oacute; h&agrave;ng nh&aacute;i, h&agrave;ng k&eacute;m chất lượng. Trước khi l&agrave; người cung cấp sản phẩm cho người ti&ecirc;u d&ugrave;ng ch&uacute;ng t&ocirc;i cũng đ&atilde; l&agrave; những kh&aacute;ch h&agrave;ng, cũng phải lựa chọn sản phẩm cho m&igrave;nh. V&igrave; vậy ch&uacute;ng t&ocirc;i c&oacute; thể hiểu được sự lo lắng của kh&aacute;ch h&agrave;ng về chất lượng của sản phẩm m&agrave; m&igrave;nh đ&atilde; chọn lựa. Xuất ph&aacute;t từ l&yacute; do tr&ecirc;n m&agrave;&nbsp;<strong>Panpic&nbsp;</strong>đ&atilde; đề ra phương ch&acirc;m ph&aacute;t triển ch&iacute;nh l&agrave; &ldquo;chất lượng v&agrave; dịch vụ&rdquo; Ch&uacute;ng t&ocirc;i xin cam kết với Qu&yacute; kh&aacute;ch h&agrave;ng:</p>\r\n\r\n<figure><img alt=\"panpic cam ket chat luong dich vu san pham\" height=\"842\" loading=\"lazy\" src=\"https://panpic.vn/images/pic/panpic-cam-ket-chat-luong-dich-vu.jpg\" width=\"632\" />\r\n<figcaption>Panpic cam kết chất lượng sản phẩm phần mềm, web app, phần mềm&nbsp;<a href=\"https://www.panpic.vn/\" rel=\"noreferrer noopener\" target=\"_blank\">thiết kế web</a></figcaption>\r\n</figure>\r\n\r\n<ul>\r\n	<li>Cung cấp cho c&aacute;c kh&aacute;ch h&agrave;ng những sản phẩm phần mềm tốt với gi&aacute; cả cạnh tranh (<em>đi k&egrave;m với những chế độ dịch vụ hậu m&atilde;i tốt nhất</em>).</li>\r\n	<li>Đặt chữ t&iacute;n l&ecirc;n h&agrave;ng đầu.</li>\r\n	<li>Tự đặt m&igrave;nh v&agrave;o địa vị của kh&aacute;ch h&agrave;ng.</li>\r\n	<li>Ch&uacute;ng t&ocirc;i&nbsp;l&agrave;m h&agrave;i l&ograve;ng kh&aacute;ch h&agrave;ng bằng chất lượng v&agrave; th&aacute;i độ phục vụ chuy&ecirc;n nghiệp.</li>\r\n</ul>\r\n\r\n<h2>CHỨNG THƯ CAM KẾT BẢO H&Agrave;NH</h2>\r\n\r\n<ol>\r\n	<li><strong>Thời Gian Bảo H&agrave;nh</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li>Với c&aacute;c sản phẩm phần mềm website sử dụng hosting tại Panpic, ch&uacute;ng t&ocirc;i sẽ thực việc bảo h&agrave;nh, bảo tr&igrave; miễn ph&iacute; trong suốt qu&aacute; tr&igrave;nh chạy.</li>\r\n	<li>Nếu qu&yacute; kh&aacute;ch h&agrave;ng sử dụng hosting tại nơi kh&aacute;c, Panpic vẫn hỗ trợ bảo h&agrave;nh miễn ph&iacute; 1 năm kể từ ng&agrave;y nghiệm thu dự &aacute;n.</li>\r\n</ul>\r\n\r\n<ol start=\"2\">\r\n	<li><strong>C&aacute;c H&igrave;nh Thức Bảo H&agrave;nh Bảo Tr&igrave;</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li>Nh&acirc;n vi&ecirc;n kỹ thuật của Panpic sẽ tiến h&agrave;nh khắc phục lỗi hoặc sự cố đối với website khi c&oacute; th&ocirc;ng b&aacute;o từ kh&aacute;ch h&agrave;ng.</li>\r\n	<li>C&aacute;c h&igrave;nh thức hỗ trợ từ xa như, Email, Điện thoại, Teamviewer, Skype, Zalo hoặc&nbsp;<a href=\"https://ticket.panpic.vn/\" rel=\"noopener\" target=\"_blank\">phần mềm hỗ trợ quản l&yacute; Ticket</a>&nbsp;của Panpic với c&aacute;c lỗi đơn giản.</li>\r\n</ul>\r\n\r\n<ol start=\"3\">\r\n	<li><strong>Phạm Vi Bảo H&agrave;nh</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li>Dịch vụ bảo h&agrave;nh giới hạn trong việc sửa lỗi chức năng website do Panpic x&acirc;y dựng (<em>C&aacute;c chức năng ghi trong hợp đồng dịch vụ số &hellip;&hellip;&nbsp;/HĐDV2016</em>)</li>\r\n	<li>C&aacute;c trường hợp kh&ocirc;ng thuộc phạm vi bảo h&agrave;nh</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>Lỗi của chương tr&igrave;nh kh&aacute;c, phần mềm hệ thống, cấu h&igrave;nh hệ điều h&agrave;nh server, phần mềm mạng, &hellip;vv</li>\r\n	<li>Lỗi dữ liệu v&agrave; phần cứng.</li>\r\n	<li>Lỗi do vận h&agrave;nh kh&ocirc;ng đ&uacute;ng hướng dẫn sử dụng, do sự v&ocirc; &yacute;, cầu thả.</li>\r\n	<li>Lỗi do kh&aacute;ch h&agrave;ng tự &yacute; can thiệp v&agrave;o c&aacute;c file m&atilde; code lập tr&igrave;nh.</li>\r\n	<li>Lỗi do tai nạn ch&aacute;y nổ, thi&ecirc;n tai do m&ocirc;i trường g&acirc;y ra.</li>\r\n</ul>\r\n', 'Cam Kết Chất Lượng Dịch Vụ Sản Phẩm Phần Mềm Website', 'Cam Kết Chất Lượng Dịch Vụ Sản Phẩm Phần Mềm Website, Chứng thư cam kết bảo hành'),
(12, 'vi', 'dieu-khoan-su-dung', 'Điều khoản sử dụng', '', '<h2>QUY ĐỊNH V&Agrave; ĐIỀU KHOẢN SỬ DỤNG</h2>\r\n\r\n<p><strong>1.</strong>&nbsp;Ch&uacute;ng t&ocirc;i kh&ocirc;ng chịu tr&aacute;ch nhiệm v&agrave; kh&ocirc;ng đảm bảo về t&iacute;nh ch&iacute;nh x&aacute;c của những th&ocirc;ng tin từ bất kỳ ai gửi đến m&aacute;y chủ v&agrave; kh&ocirc;ng chịu bất cứ tr&aacute;ch nhiệm ph&aacute;p l&yacute; hoặc bồi thường thiệt hại n&agrave;o về việc mất m&aacute;t hay hư hỏng đối với dữ liệu được lưu trữ tr&ecirc;n m&aacute;y chủ. Người sử dụng c&oacute; tr&aacute;ch nhiệm thực hiện việc duy tr&igrave; v&agrave; bảo quản dữ liệu tr&ecirc;n m&aacute;y chủ.</p>\r\n\r\n<p><strong>2.</strong>&nbsp;Kh&aacute;ch h&agrave;ng sử dụng dịch vụ sẽ phải cam kết phản &aacute;nh trung thực về chất lượng dịch vụ tr&ecirc;n mọi phương tiện truyền th&ocirc;ng, website, diễn đ&agrave;n&hellip; Mọi phản &aacute;nh đều phải k&egrave;m theo bằng chứng x&aacute;c thực. Ch&uacute;ng t&ocirc;i c&oacute; quyền đơn phương chấm dứt hợp đồng nếu ph&aacute;t hiện nội dung phản &aacute;nh kh&ocirc;ng x&aacute;c thực v&agrave; mang t&iacute;nh c&ocirc;ng k&iacute;ch, b&ocirc;i nhọ l&agrave;m ảnh hưởng ti&ecirc;u cực đến uy t&iacute;n của nh&agrave; cung cấp.</p>\r\n\r\n<p><strong>3.</strong>&nbsp;Người sử dụng phải tự chịu tr&aacute;ch nhiệm v&agrave; đảm bảo với Panpic&nbsp;trong việc sử dụng website của m&igrave;nh tr&ecirc;n m&aacute;y chủ v&agrave;o những mục đ&iacute;ch hợp ph&aacute;p.</p>\r\n\r\n<p><strong>4.</strong>&nbsp;Kh&ocirc;ng d&ugrave;ng m&aacute;y chủ, hosting share v&agrave;o bất kỳ mục đ&iacute;ch/h&igrave;nh thức n&agrave;o vi phạm ph&aacute;p luật Việt Nam, đặc biệt về vấn đề bản quyền phần mềm, ca kh&uacute;c&hellip; Đồng thời c&oacute; tr&aacute;ch nhiệm kiểm so&aacute;t v&agrave; ngăn cấm người kh&aacute;c l&agrave;m điều đ&oacute; tr&ecirc;n website của m&igrave;nh.<br />\r\nNếu ch&uacute;ng t&ocirc;i nhận được th&ocirc;ng b&aacute;o về việc vi phạm bản quyền, ch&uacute;ng t&ocirc;i sẽ tiến h&agrave;nh kiểm tra v&agrave; kh&oacute;a t&agrave;i khoản khi x&aacute;c nhận việc vi phạm. Trong trường hợp vi phạm kh&ocirc;ng được xử l&yacute; sau 24h kể từ khi được th&ocirc;ng b&aacute;o v&agrave; tạm kh&oacute;a th&igrave; ch&uacute;ng t&ocirc;i sẽ kh&oacute;a t&agrave;i khoản vĩnh viễn m&agrave; kh&ocirc;ng ho&agrave;n trả lại ph&iacute; dịch vụ.</p>\r\n\r\n<p><strong>5.</strong>&nbsp;Người sử dụng kh&ocirc;ng được đưa l&ecirc;n m&aacute;y chủ những dữ liệu mang t&iacute;nh bất hợp ph&aacute;p, đe dọa, lừa dối, th&ugrave; hằn, xuy&ecirc;n tạc, n&oacute;i xấu, x&uacute;c phạm&hellip; hay c&aacute;c h&igrave;nh thức bị ngăn cấm kh&aacute;c dưới bất kỳ h&igrave;nh thức n&agrave;o.</p>\r\n\r\n<p><strong>6.</strong>&nbsp;Kh&aacute;ch h&agrave;ng cần lưu giữ một c&aacute;ch an to&agrave;n c&aacute;c th&ocirc;ng tin nhận biết, mật khẩu hay những th&ocirc;ng tin kh&aacute;c li&ecirc;n quan đến t&agrave;i khoản của dịch vụ hoặc t&agrave;i khoản quản l&yacute; kh&aacute;ch h&agrave;ng v&agrave; lập tức th&ocirc;ng b&aacute;o cho ch&uacute;ng t&ocirc;i khi bạn ph&aacute;t hiện c&aacute;c h&igrave;nh thức truy cập tr&aacute;i ph&eacute;p bằng t&agrave;i khoản của bạn hoặc c&aacute;c sơ hở về bảo mật, bao gồm việc mất m&aacute;t, đ&aacute;nh cắp hoặc để lộ th&ocirc;ng tin về mật khẩu v&agrave; c&aacute;c th&ocirc;ng tin kh&aacute;c.</p>\r\n\r\n<p><strong>7.</strong>&nbsp;Bạn sẽ phải chịu tr&aacute;ch nhiệm trước ph&aacute;p luật với&nbsp;<strong>nội dung website</strong>&nbsp;của bạn v&agrave; sẽ phải chấp nhận mọi h&igrave;nh thức xử l&yacute; từ ph&iacute;a cơ quan chức năng (nếu c&oacute;) nếu như nội dung vi phạm luật ph&aacute;p nước Cộng h&ograve;a X&atilde; hội Chủ nghĩa Việt Nam.</p>\r\n\r\n<p><strong>8.</strong>&nbsp;Người sử dụng kh&ocirc;ng được gửi email dưới mọi h&igrave;nh thức mang mục đ&iacute;ch ph&aacute; hoại hay ph&aacute;t t&aacute;n thư r&aacute;c từ m&aacute;y chủ hosting của Panpic. Bao gồm tất cả những chương tr&igrave;nh gửi mail qu&aacute; số lượng quy định (100 emails/lần), v&iacute; dụ: bomb mail.</p>\r\n\r\n<p><strong>9.</strong>&nbsp;Người sử dụng kh&ocirc;ng sử dụng c&aacute;c m&atilde; nguồn c&oacute; khả năng l&agrave;m tắc nghẽn hoặc đ&igrave;nh trệ hệ thống, g&acirc;y cạn kiệt t&agrave;i nguy&ecirc;n hệ thống, l&agrave;m qu&aacute; tải bộ vi xử l&yacute; v&agrave; bộ nhớ.<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><u>Ghi ch&uacute;</u>:</p>\r\n\r\n<ul>\r\n	<li>Quy định sử dụng c&oacute; thể sẽ được thay đổi v&agrave; cập nhật cho ph&ugrave; hợp với từng thời điểm v&agrave; loại h&igrave;nh dịch vụ.</li>\r\n</ul>\r\n', 'Quy định và Điều khoản sử dụng', 'Quy định chính sách và điều khoản sử dụng của công ty PANPIC'),
